    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for k in (0, 1):
            vals = [row[3*j+k] for j in range(5)]
            counts = {v: vals.count(v) for v in set(vals)}
            value = max(counts, key=counts.get)
            for j in range(5):
                out[r][3*j+k] = value
